arguments.file_text:
namespace sv_89f53e059db6451cb17ed1b26fd5c526.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_89f53e059db6451cb17ed1b26fd5c526.Services

<div class="channel-item @(IsActive ? "active" : "")" @onclick="HandleClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-description">@Channel.Description</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback<Channel> OnSelected { get; set; }

    private async Task HandleClick()
    {
        await OnSelected.InvokeAsync(Channel);
    }
}

@using sv_89f53e059db6451cb17ed1b26fd5c526.Services

<div class="channel-list">
    <h4 class="channel-list-header">Channels</h4>
    @foreach (var channel in Channels)
    {
        <ChannelItem Channel="channel"
                     IsActive="channel.Id == SelectedChannelId"
                     OnSelected="OnChannelSelected" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = new();
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<Channel> OnChannelSelected { get; set; }
}

@using sv_89f53e059db6451cb17ed1b26fd5c526.Services

<div class="message-item" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" @onclick="() => OnReact.InvokeAsync(Message.Id)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount replies
        </button>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">Reply</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker">React</button>
        </div>

        @if (showEmojiPicker)
        {
            <EmojiPicker OnEmojiSelected="HandleEmojiSelected" />
        }
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<int> OnReact { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactionSelected { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private void ToggleEmojiPicker()
    {
        showEmojiPicker = !showEmojiPicker;
    }

    private async Task HandleEmojiSelected(string emoji)
    {
        showEmojiPicker = false;
        await OnReactionSelected.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@using sv_89f53e059db6451cb17ed1b26fd5c526.Services

<div class="message-area">
    @if (CurrentChannel is not null)
    {
        <div class="message-area-header">
            <h3># @CurrentChannel.Name</h3>
            <p>@CurrentChannel.Description</p>
        </div>

        <div class="message-list" @onscroll="HandleScroll">
            @if (IsLoadingMore)
            {
                <div class="loading-indicator">Loading older messages...</div>
            }
            @foreach (var message in Messages)
            {
                <MessageItem Message="message"
                             ReplyCount="GetReplyCount(message.Id)"
                             OnOpenThread="OnOpenThread"
                             OnReact="OnReact"
                             OnReactionSelected="OnReactionSelected" />
            }
        </div>

        <div class="message-input-area">
            <textarea class="message-input" @bind="newMessageContent" @bind:event="oninput"
                      placeholder="Message #@CurrentChannel.Name" rows="2"></textarea>
            <button class="send-btn" @onclick="HandleSend" disabled="@string.IsNullOrWhiteSpace(newMessageContent)">
                Send
            </button>
        </div>
    }
    else
    {
        <div class="no-channel-selected">
            <p>Select a channel to start chatting</p>
        </div>
    }
</div>

@code {
    [Parameter] public Channel? CurrentChannel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<int> OnReact { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReactionSelected { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }

    private string newMessageContent = string.Empty;

    private int GetReplyCount(int messageId)
    {
        return ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;
    }

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading more messages
        await OnLoadMore.InvokeAsync();
    }

    private async Task HandleSend()
    {
        if (string.IsNullOrWhiteSpace(newMessageContent)) return;
        var content = newMessageContent;
        newMessageContent = string.Empty;
        await OnSendMessage.InvokeAsync(content);
    }
}

@using sv_89f53e059db6451cb17ed1b26fd5c526.Services

<div class="thread-message">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.Now - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d");
    }
}

@using sv_89f53e059db6451cb17ed1b26fd5c526.Services

<div class="thread-panel">
    <div class="thread-header">
        <h4>Thread</h4>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p class="message-content">@RootMessage.Content</p>
        </div>
    }

    <div class="thread-replies">
        @foreach (var reply in Replies)
        {
            <ThreadMessage Message="reply" />
        }
    </div>

    <div class="thread-input-area">
        <textarea class="thread-input" @bind="replyContent" @bind:event="oninput"
                  placeholder="Reply..." rows="2"></textarea>
        <button class="reply-btn" @onclick="HandleReply" disabled="@string.IsNullOrWhiteSpace(replyContent)">
            Reply
        </button>
    </div>
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnReply { get; set; }

    private string replyContent = string.Empty;

    private async Task HandleReply()
    {
        if (string.IsNullOrWhiteSpace(replyContent)) return;
        var content = replyContent;
        replyContent = string.Empty;
        await OnReply.InvokeAsync(content);
    }
}

@page "/chat"
@using sv_89f53e059db6451cb17ed1b26fd5c526.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <div class="chat-sidebar">
        <ChannelList Channels="channels"
                     SelectedChannelId="selectedChannelId"
                     OnChannelSelected="HandleChannelSelected" />
    </div>

    <div class="chat-main">
        <MessageArea CurrentChannel="selectedChannel"
                     Messages="messages"
                     ThreadReplyCounts="threadReplyCounts"
                     IsLoadingMore="isLoadingMore"
                     OnLoadMore="HandleLoadMore"
                     OnOpenThread="HandleOpenThread"
                     OnReact="HandleReact"
                     OnReactionSelected="HandleReactionSelected"
                     OnSendMessage="HandleSendMessage" />
    </div>

    @if (threadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="HandleCloseThread"
                         OnReply="HandleThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = new();
    private Channel? selectedChannel;
    private int selectedChannelId;
    private List<Message> messages = new();
    private Dictionary<int, int> threadReplyCounts = new();
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await HandleChannelSelected(channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        selectedChannel = channel;
        selectedChannelId = channel.Id;
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messageSkip = messages.Count;
        await ChatService.MarkChannelReadAsync(channel.Id);
        await UpdateThreadReplyCounts();
    }

    private async Task HandleLoadMore()
    {
        if (isLoadingMore || selectedChannel is null) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(selectedChannel.Id, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
        }
        isLoadingMore = false;
    }

    private async Task HandleSendMessage(string content)
    {
        if (selectedChannel is null) return;
        var message = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(message);
    }

    private async Task HandleOpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void HandleCloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = new();
    }

    private async Task HandleThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        await UpdateThreadReplyCounts();
    }

    private async Task HandleReact(int messageId)
    {
        // No-op; reaction selection handled by HandleReactionSelected
        await Task.CompletedTask;
    }

    private async Task HandleReactionSelected((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect new reaction
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messageSkip);
        }
    }

    private async Task UpdateThreadReplyCounts()
    {
        threadReplyCounts = new();
        // Identify messages that have replies (messages with ReplyToId pointing to them)
