.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    border-right: 1px solid #e0e0e0;
    background: #f8f9fa;
    overflow-y: auto;
}

.chat-main {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    border-left: 1px solid #e0e0e0;
    background: #fafafa;
}

/* Channel List */
.channel-list {
    padding: 1rem;
}

.channel-list-header {
    font-size: 0.85rem;
    text-transform: uppercase;
    color: #666;
    margin-bottom: 0.75rem;
    font-weight: 600;
}

.channel-item {
    padding: 0.5rem 0.75rem;
    border-radius: 6px;
    cursor: pointer;
    margin-bottom: 2px;
    position: relative;
}

.channel-item:hover {
    background: #e9ecef;
}

.channel-item.active {
    background: #d0e7ff;
    font-weight: 500;
}

.channel-name {
    font-size: 0.95rem;
    font-weight: 500;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 0.5rem;
    right: 0.5rem;
    background: #dc3545;
    color: white;
    font-size: 0.7rem;
    font-weight: 600;
    padding: 0.1rem 0.4rem;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

