    color: #666;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem 1.25rem;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #888;
    font-size: 0.85rem;
}

.no-channel-selected {
