namespace sv_89f53e059db6451cb17ed1b26fd5c526.Services;

/// <summary>
/// In-memory fake implementation for development/testing.
/// Replace with a real implementation that calls your backend API.
/// </summary>
public class FakeChatService : IChatService
{
    private readonly List<Channel> _channels = new()
    {
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering topics and code reviews", 0),
        new(3, "random", "Off-topic conversations", 1),
    };

    private readonly List<Message> _messages = new()
    {
        new(1, 1, "Alice", "Hey everyone! Welcome to the team chat.", DateTime.Now.AddHours(-2), null, new() { new("👍", new() { "Bob" }) }),
        new(2, 1, "Bob", "Thanks Alice! Excited to be here.", DateTime.Now.AddHours(-1.5), null, new()),
        new(3, 1, "Charlie", "Has anyone seen the new design specs?", DateTime.Now.AddMinutes(-45), null, new() { new("👍", new() { "Alice", "Bob" }) }),
        new(4, 1, "Alice", "Yes! They look great. Let's discuss in a thread.", DateTime.Now.AddMinutes(-30), 3, new()),
        new(5, 2, "Dave", "PR #42 is ready for review.", DateTime.Now.AddMinutes(-20), null, new() { new("🚀", new() { "Alice" }) }),
        new(6, 2, "Alice", "I'll take a look this afternoon.", DateTime.Now.AddMinutes(-15), null, new()),
    };

    private int _nextMessageId = 100;

    public Task<List<Channel>> GetChannelsAsync() =>
        Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take) =>
        Task.FromResult(
            _messages
                .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
                .OrderBy(m => m.SentAt)
                .Skip(skip)
                .Take(take)
                .ToList());

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var message = new Message(
            _nextMessageId++, channelId, "You", content, DateTime.Now, replyToId, new());
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId) =>
        Task.FromResult(
            _messages
                .Where(m => m.ReplyToId == rootMessageId)
                .OrderBy(m => m.SentAt)
                .ToList());

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new() { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

